SELECT TOP 20 *
FROM dbo.customer;

--#total revenue generated by male vs. female customers
select gender, sum(purchase_amount) as revenue
from customer
group by gender

--customer used a discount but still spent more than the average purchase amount
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (
      SELECT AVG(purchase_amount)
      FROM customer
  );

  --top 5 products with the highest average review ratings
   SELECT TOP 5
    item_purchased,
    ROUND(AVG(review_rating), 2) AS [Average Product Ratings]
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC;

--compare  the average  purchase amounts between standard and express shipping
SELECT 
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS [Average Purchase Amount]
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

--do subcribed customers spend more? compare average spend total  revenue
--between subcribers and non-subscribers.
SELECT 
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS avg_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;

--which  5 products have the highest percentage of purchases with discounts applied?
SELECT TOP 5
    item_purchased,
    ROUND(
        SUM(CASE 
                WHEN discount_applied = 'Yes' THEN 1 
                ELSE 0 
            END) * 100.0 / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC;

--top 3 most purchased products within each category
WITH item_counts AS (
    SELECT 
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category 
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT 
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;

--Are customers who are repeat buyers (more than 5 previous  purchases) also likely to subscribe?
SELECT 
    subscription_status,
    COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--what is the revenue contribution of each age group?
select age_group,
SUM(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;